package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Connection.KeyVal;
import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.helper.HttpConnection;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Entities;
import org.jsoup.nodes.FormElement;
import org.jsoup.nodes.Tag;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class FormElement_formData_TriageGen1Test {

    private FormElement formElement;
    private Tag tag;

    @Before
    public void setUp() {
        tag = new Tag(Tag.valueOf("form"));
    }

    @Test
    public void testEmptyForm() {
        formElement = new FormElement(tag, "", new Attributes());
        List<KeyVal> formData = formElement.formData();
        assertTrue(formData.isEmpty());
    }

    @Test
    public void testDisabledInput() {
        Element input = new Element(Tag.valueOf("input"), "", new Attributes().put("name", "test").put("disabled", ""));
        formElement = new FormElement(tag, "", new Attributes());
        formElement.addElement(input);
        List<KeyVal> formData = formElement.formData();
        assertTrue(formData.isEmpty());
    }

    @Test
    public void testInputWithoutName() {
        Element input = new Element(Tag.valueOf("input"), "", new Attributes().put("type", "text"));
        formElement = new FormElement(tag, "", new Attributes());
        formElement.addElement(input);
        List<KeyVal> formData = formElement.formData();
        assertTrue(formData.isEmpty());
    }

    @Test
    public void testValidTextInput() {
        Element input = new Element(Tag.valueOf("input"), "", new Attributes().put("name", "username").put("value", "user123"));
        formElement = new FormElement(tag, "", new Attributes());
        formElement.addElement(input);
        List<KeyVal> formData = formElement.formData();
        assertEquals(1, formData.size());
        assertEquals("user123", formData.get(0).value());
    }

    @Test
    public void testValidSelectElementWithValue() {
        Element select = new Element(Tag.valueOf("select"), "", new Attributes().put("name", "color"));
        select.appendChild(new Element(Tag.valueOf("option"), "", new Attributes().put("value", "red").put("selected", "")));
        formElement = new FormElement(tag, "", new Attributes());
        formElement.addElement(select);
        List<KeyVal> formData = formElement.formData();
        assertEquals(1, formData.size());
        assertEquals("red", formData.get(0).value());
    }

    @Test
    public void testValidSelectElementWithoutSelectedOption() {
        Element select = new Element(Tag.valueOf("select"), "", new Attributes().put("name", "color"));
        select.appendChild(new Element(Tag.valueOf("option"), "", new Attributes().put("value", "blue")));
        formElement = new FormElement(tag, "", new Attributes());
        formElement.addElement(select);
        List<KeyVal> formData = formElement.formData();
        assertEquals(1, formData.size());
        assertEquals("blue", formData.get(0).value());
    }

    @Test
    public void testCheckedCheckbox() {
        Element checkbox = new Element(Tag.valueOf("input"), "", new Attributes().put("name", "agree").put("type", "checkbox").put("checked", "").put("value", "yes"));
        formElement = new FormElement(tag, "", new Attributes());
        formElement.addElement(checkbox);
        List<KeyVal> formData = formElement.formData();
        assertEquals(1, formData.size());
        assertEquals("yes", formData.get(0).value());
    }

    @Test
    public void testUncheckedCheckbox() {
        Element checkbox = new Element(Tag.valueOf("input"), "", new Attributes().put("name", "agree").put("type", "checkbox"));
        formElement = new FormElement(tag, "", new Attributes());
        formElement.addElement(checkbox);
        List<KeyVal> formData = formElement.formData();
        assertTrue(formData.isEmpty());
    }

    @Test
    public void testCheckedRadio() {
        Element radio = new Element(Tag.valueOf("input"), "", new Attributes().put("name", "gender").put("type", "radio").put("checked", "").put("value", "male"));
        formElement = new FormElement(tag, "", new Attributes());
        formElement.addElement(radio);
        List<KeyVal> formData = formElement.formData();
        assertEquals(1, formData.size());
        assertEquals("male", formData.get(0).value());
    }

    @Test
    public void testUncheckedRadio() {
        Element radio = new Element(Tag.valueOf("input"), "", new Attributes().put("name", "gender").put("type", "radio"));
        formElement = new FormElement(tag, "", new Attributes());
        formElement.addElement(radio);
        List<KeyVal> formData = formElement.formData();
        assertTrue(formData.isEmpty());
    }

    @Test
    public void testMultipleInputs() {
        Element input1 = new Element(Tag.valueOf("input"), "", new Attributes().put("name", "username").put("value", "user123"));
        Element input2 = new Element(Tag.valueOf("input"), "", new Attributes().put("name", "password").put("value", "pass456"));
        formElement = new FormElement(tag, "", new Attributes());
        formElement.addElement(input1);
        formElement.addElement(input2);
        List<KeyVal> formData = formElement.formData();
        assertEquals(2, formData.size());
        assertEquals("user123", formData.get(0).value());
        assertEquals("pass456", formData.get(1).value());
    }
}
